procedure multiply(x, y: nonnegative integers)
r := x;
s := y;
a := 0;
while s ≠ 0 do
    if 3 | s then
        r := r + r + r;
        s := s/3;
    else if 3 | (s - 1) then
        a := a + r;
        r := r + r + r;
        s := (s - 1)/3;
    else
        a := a + r + r;
        r := r + r + r;
        s := (s - 2)/3;
return a;
